"    if(b) setTheme(b.getAttribute('data-theme'));\n"
"  });\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * Navigation: definition -> render -> view. NAV ids map 1:1 to views{}.\n"
" * ===================================================================== */\n"
"var NAV=[\n"
"  {id:'dashboard',icon:'M3 3h7v9H3zM14 3h7v5h-7zM14 12h7v9h-7zM3 16h7v5H3z'},\n"
"  {id:'devices',icon:'M9 3a2 2 0 0 0-2 2v2a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2H9zM5 12v7a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-7'},\n"
"  {id:'entities',icon:'M12 3 3 8v8l9 5 9-5V8l-9-5zM3 8l9 5 9-5M12 13v8'},\n"
"  {id:'rules',icon:'M13 2 4 14h6l-1 8 9-12h-6l1-8z'},\n"
"  {id:'skills',icon:'M12 3l2.1 5.4L20 10l-5.9 1.6L12 17l-2.1-5.4L4 10l5.9-1.6L12 3zM19 17l1 2.4 2.4 1-2.4 1L19 24l-1-2.6-2.4-1 2.4-1L19 17z'},\n"
"  {id:'logs',icon:'M4 6h16M4 12h16M4 18h10'},\n"
"  {id:'system',icon:'M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z'},\n"
"  {id:'network',icon:'M5 13a10 10 0 0 1 14 0M8.5 16.5a5 5 0 0 1 7 0M2 9.5a15 15 0 0 1 20 0M12 19l.01 0'}\n"
"];\n"
"function iconSvg(path){ return '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"'+path+'\"/></svg>'; }\n"
"function buildNav(){\n"
"  navTabs.innerHTML='';\n"
"  NAV.forEach(function(n){\n"
"    var b=el('button',{'type':'button','class':'tab','data-tab':n.id});\n"
"    b.innerHTML=iconSvg(n.icon)+'<span data-i18n=\"nav.'+n.id+'\"></span>';\n"
"    navTabs.appendChild(b);\n"
"  });\n"
"  applyI18n(navTabs);\n"
"  var langEl=document.querySelector('.lang-switch');\n"
"  langEl.addEventListener('click',function(e){\n"
"    var b=e.target.closest?e.target.closest('.lang-btn'):null;\n"
"    if(b) setLang(b.getAttribute('data-lang'));\n"
"  });\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * UI state is kept apart from the DOM. DOM attributes are only used for\n"
" * bindings (data-field / data-action / data-*key), never for source data.\n"
" * ===================================================================== */\n"
"var uiState={\n"
"  activeView:'dashboard',\n"
"  formActive:false,\n"
"  editingRuleId:null,\n"
"  pending:new Set()\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * Tiny DOM update helpers - each skips the DOM write when unchanged.\n"
" * ===================================================================== */\n"
"function setText(node,value){\n"
"  if(!node) return;\n"
"  var next=String(value==null?'':value);\n"
"  if(node.textContent!==next) node.textContent=next;\n"
"}\n"
"function setClass(node,cls,on){\n"
"  if(!node) return;\n"
"  if(on) node.classList.add(cls); else node.classList.remove(cls);\n"
"}\n"
"function setDisabled(node,d){\n"
"  if(!node) return;\n"
"  if(node.disabled!==!!d) node.disabled=!!d;\n"
"}\n"
"function setAttr(node,name,value){\n"
"  if(!node) return;\n"
"  var next=String(value==null?'':value);\n"
"  if(node.getAttribute(name)!==next) node.setAttribute(name,next);\n"
"}\n"
"function setValue(node,value){\n"
"  if(!node) return;\n"
"  var next=String(value==null?'':value);\n"
"  if(node.value!==next) node.value=next;\n"
"}\n"
"\n"
"/* DOM builder: minimal, no framework. */\n"
"function el(tag,attrs,children){\n"
"  var n=document.createElement(tag);\n"
"  if(attrs) for(var k in attrs){\n"
"    if(!Object.prototype.hasOwnProperty.call(attrs,k)) continue;\n"
"    if(k==='class') n.className=attrs[k];\n"
"    else if(k==='text') n.textContent=attrs[k];\n"
"    else n.setAttribute(k,attrs[k]);\n"
"  }\n"
"  if(children){\n"
"    (Array.isArray(children)?children:[children]).forEach(function(c){\n"
"      if(c==null) return;\n"
"      n.appendChild(typeof c==='string'?document.createTextNode(c):c);\n"
"    });\n"
"  }\n"
"  return n;\n"
"}\n"
"function insertAt(container,node,idx){\n"
"  var kids=container.children;\n"
"  if(idx>=kids.length) container.appendChild(node);\n"
"  else container.insertBefore(node,kids[idx]);\n"
"}\n"
"\n"
"/* reconcileCollection(container, list, keyFn, attr, create, apply)\n"
" * In-place diff: existing key -> apply() in place; new key -> create one\n"
" * node; missing key -> remove one node. Order is preserved. Never wipes or\n"
" * rebuilds the container, so focus/unpersisted DOM state survives refresh.\n"
" * `attr` is the stable-key attribute (data-*-key) on each child node. */\n"
"function reconcileCollection(container,list,keyFn,attr,create,apply){\n"
"  var byKey={};\n"
"  list.forEach(function(it){ byKey[keyFn(it)]=it; });\n"
"  Array.prototype.slice.call(container.children).forEach(function(node){\n"
"    var k=node.getAttribute(attr);\n"
"    if(k==null||!byKey[k]) container.removeChild(node);\n"
"  });\n"
"  var kids=container.children;\n"
"  list.forEach(function(it,idx){\n"
"    var k=keyFn(it);\n"
"    var node=null;\n"
"    Array.prototype.some.call(kids,function(n){ if(n.getAttribute(attr)===k){node=n;return true;} return false; });\n"
"    if(!node){\n"
"      node=create(it);\n"
"      node.setAttribute(attr,k);\n"
"      apply(it,node);\n"
"      insertAt(container,node,idx);\n"
"    } else {\n"
"      apply(it,node);\n"
"      if(kids[idx]!==node) container.insertBefore(node,kids[idx]||null);\n"
"    }\n"
"  });\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * API + online status\n"
" * ===================================================================== */\n"
"function esc(s){\n"
"  return String(s==null?'':s)\n"
"    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')\n"
"    .replace(/\"/g,'&quot;').replace(/'/g,'&#39;');\n"
"}\n"
"function fmtBool(v){ return v===true?t('common.on'):(v===false?t('common.off'):esc(v)); }\n"
"function fmtTs(sec){ if(!sec) return '—'; return new Date(sec*1000).toLocaleTimeString(lang); }\n"
"function badgeForStatus(s){\n"
"  if(!s) return '';\n"
"  var st=String(s);\n"
"  if(st==='STATE_CONFIRMED'||st==='CONFIRMED') return 'badge-confirmed';\n"
"  if(st==='FAILED'||st==='TIMEOUT') return 'badge-error';\n"
"  return 'badge-pending';\n"
"}\n"
"function apiFetch(path,opts){\n"
"  opts=opts||{};\n"
"  var ctrl=new AbortController();\n"
"  var timer=setTimeout(function(){ctrl.abort();},8000);\n"
"  var init={headers:{'Content-Type':'application/json'},signal:ctrl.signal};\n"
"  if(opts.method){ init.method=opts.method; }\n"
"  if(opts.body){ init.body=opts.body; }\n"
"  return fetch(API+path,init).then(function(r){\n"
"      clearTimeout(timer);\n"
"      return r.text().then(function(txt){\n"
"        var j=null;\n"
"        try{ j=JSON.parse(txt); }catch(e){ j=null; }\n"
"        if(!j){ throw new Error('Invalid JSON response from '+path); }\n"
"        if(!j.ok){ throw new Error((j.error&&j.error.code?j.error.code+': ':'')+(j.error&&j.error.message?j.error.message:'request failed')); }\n"
"        return j.data;\n"
"      });\n"
"    }).catch(function(e){\n"
"      clearTimeout(timer);\n"
"      if(e&&e.name==='AbortError') throw new Error('Timeout: '+path+' unreachable');\n"
"      throw e;\n"
"    });\n"
"}\n"
"function setOnline(b){\n"
"  statusDot.className=b?'dot ok':'dot';\n"
"  setText(statusTextEl,t(b?'common.online':'common.offline'));\n"
"}\n"
"function setNetLabel(txt){ setText(sysInfoEl,txt); }\n"
"/* Human label for the connection the device is currently hosting. */\n"
"function netLabelFor(s){\n"
"  if(!s||!s.network) return '';\n"
"  return s.network==='AP'||s.network==='APSTA'?('AP · '+(s.ssid||'')):'STA';\n"
"}\n"
"var toastTimer;\n"
"function showError(err){\n"
"  toastEl.textContent=(t('common.error')+': ')+(err&&err.message?err.message:'unknown');\n"
"  toastEl.style.display='block';\n"
"  clearTimeout(toastTimer);\n"
"  toastTimer=setTimeout(function(){ toastEl.style.display='none'; },4000);\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * Polling engine: active view only + request dedup + stale protection.\n"
" * Each view keeps: gen (stale-response check), inflight (dedup), mount/refresh/update.\n"
" * ===================================================================== */\n"
"var views={};\n"
"function makeRefresh(path,viewName){\n"
"  return function(gen){\n"
"    return apiFetch(path).then(function(data){\n"
"      if(gen===views[viewName].gen){\n"
"        setOnline(true);\n"
"        views[viewName].update(data);\n"
"      }\n"
"    });\n"
"  };\n"
"}\n"
"function runViewRefresh(v){\n"
"  if(!v||!v.refresh||v.inflight) return;\n"
"  if(v.pollable===false) return;\n"
"  if(uiState.formActive) return;\n"
"  if(typeof v.gen!=='number') v.gen=0;\n"
"  v.inflight=true;\n"
"  var gen=++v.gen;\n"
"  v.refresh(gen).then(function(){ v.inflight=false; })\n"
"    .catch(function(){ v.inflight=false; setOnline(false); });\n"
"}\n"
"function showView(name){\n"
"  uiState.activeView=name;\n"
"  var v=views[name];\n"
"  Array.prototype.forEach.call(navTabs.querySelectorAll('.tab'),function(b){\n"
"    setClass(b,'active',b.getAttribute('data-tab')===name);\n"
"  });\n"
"  var host=document.getElementById('view-'+name);\n"
"  if(!host){\n"
"    host=document.createElement('div');\n"
"    host.id='view-'+name;\n"
"    main.appendChild(host);\n"
"    v.host=host;\n"
"    if(v.mount) v.mount(host);\n"
"  }\n"
"  Object.keys(views).forEach(function(n){\n"
"    var h=document.getElementById('view-'+n);\n"
"    if(h) h.style.display=(n===name)?'':'none';\n"
"  });\n"
"  if(v.refresh&&v.pollable!==false) runViewRefresh(v);\n"
"}\n"
"/* Single consistent poll interval; only the active view is fetched, and a\n"
" * view that is a form (uiState.formActive) is skipped so typing survives. */\n"
"function pollTick(){\n"
"  var v=views[uiState.activeView];\n"
"  if(v&&v.refresh&&v.pollable!==false&&!uiState.formActive) runViewRefresh(v);\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * DASHBOARD view\n"
" * ===================================================================== */\n"
"views.dashboard={\n"
"  mount:function(host){\n"
"    host.innerHTML=\n"
"      '<div class=\"grid grid-3\">'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"dash.status\">Status</h2><div class=\"metric\"><span class=\"badge badge-online\" data-i18n=\"common.online\">Online</span></div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"dash.ip\">IP Address</h2><div class=\"metric\" data-field=\"ip\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"dash.heap\">Free Heap</h2><div class=\"metric\" data-field=\"heap\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"dash.uptime\">Uptime</h2><div class=\"metric\" data-field=\"uptime\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"dash.device_count\">Device Count</h2><div class=\"metric\" data-field=\"device_count\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"dash.entity_count\">Entity Count</h2><div class=\"metric\" data-field=\"entity_count\">—</div></div>'+\n"
"      '</div>';\n"
"    applyI18n(host);\n"
"    var f={};\n"
"    ['ip','heap','uptime','device_count','entity_count'].forEach(function(n){\n"
"      f[n]=host.querySelector('[data-field=\"'+n+'\"]');\n"
"    });\n"
"    this.__f=f;\n"
"  },\n"
"  refresh:makeRefresh('/status','dashboard'),\n"
"  update:function(s){\n"
"    var f=this.__f;\n"
"    setNetLabel(netLabelFor(s));\n"
"    setText(f.ip,s.ip||'—');\n"
"    setText(f.heap,s.free_heap+' B');\n"
"    setText(f.uptime,Math.floor(s.uptime_ms/1000)+'s');\n"
"    setText(f.device_count,s.device_count);\n"
"    setText(f.entity_count,s.entity_count);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * DEVICES view\n"
" * ===================================================================== */\n"
"function deviceCardNew(){ return el('div',{'class':'card','data-device-key':''}); }\n"
"function updateDeviceCard(dev,node){\n"
"  var local=(dev.role==='dashboard');\n"
"  if(!node.__built){\n"
"    node.innerHTML=''+\n"
"      '<h2></h2>'+\n"
"      '<div class=\"entity\"><div class=\"entity-info\">'+\n"
"      '<span class=\"entity-name\" data-field=\"id\"></span>'+\n"
"      '<span class=\"entity-meta\" data-field=\"meta\"></span></div>'+\n"
"      '<span class=\"badge\" data-field=\"online\"></span></div>'+\n"
"      '<div style=\"margin-top:8px\"><span class=\"entity-meta\" data-field=\"state\"></span></div>';\n"
"    node.__built=true;\n"
"  }\n"
"  var h2=node.querySelector('h2');\n"
"  h2.textContent='';\n"
"  h2.appendChild(el('span',{'text':esc(dev.name)}));\n"
"  h2.appendChild(el('span',{'class':'badge '+(local?'badge-local':'badge-remote'),'text':local?t('common.local'):t('common.remote')}));\n"
"  setText(node.querySelector('[data-field=\"id\"]'),t('common.id')+': '+dev.device_id);\n"
"  setText(node.querySelector('[data-field=\"meta\"]'),t('common.model')+': '+(dev.model||'')+' | '+t('common.location')+': '+(dev.location||'—')+' | '+t('common.role')+': '+(dev.role||'—'));\n"
"  setText(node.querySelector('[data-field=\"state\"]'),t('common.state')+': '+esc(String(dev.state?dev.state:(dev.online?'operational':'offline'))));\n"
"  var ob=node.querySelector('[data-field=\"online\"]');\n"
"  setText(ob,dev.online?t('devices.online'):t('devices.offline'));\n"
"  setClass(ob,'badge-online',!!dev.online);\n"
"  setClass(ob,'badge-offline',!dev.online);\n"
"}\n"
"views.devices={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"section-header\"><h2 data-i18n=\"nav.devices\">Devices</h2><span class=\"empty\"></span></div><div id=\"deviceList\" class=\"grid grid-2\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#deviceList');\n"
"    this.__count=host.querySelector('.section-header .empty');\n"
"  },\n"
"  refresh:makeRefresh('/devices','devices'),\n"
"  update:function(d){\n"
"    var list=d||[];\n"
"    setText(this.__count,list.length+'');\n"
"    reconcileCollection(this.__list,list,function(x){return x.device_id;},'data-device-key',deviceCardNew,updateDeviceCard);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * ENTITIES view (architectural reference: incremental + event delegation)\n"
" * ===================================================================== */\n"
"function entityCardNew(){ return el('div',{'class':'card','data-entity-key':''}); }\n"
"function updateEntityCard(ent,node){\n"
"  var key=ent.device_id+'/'+ent.entity_id;\n"
"  if(!node.__built){\n"
"    node.innerHTML=''+\n"
"      '<h2></h2>'+\n"
"      '<div class=\"entity\"><div class=\"entity-info\">'+\n"
"      '<span class=\"entity-name\" data-field=\"devkey\"></span>'+\n"
"      '<span class=\"entity-meta\" data-field=\"meta\"></span></div>'+\n"
"      '<div style=\"display:flex;flex-direction:column;gap:4px;min-width:120px;align-items:flex-end\">'+\n"
"      '<span class=\"entity-meta\" data-field=\"cmds\"></span>'+\n"
"      '<span class=\"entity-meta\" data-field=\"reliability\"></span></div></div>'+\n"
"      '<div style=\"display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:8px\">'+\n"
"      '<span class=\"entity-meta\" data-field=\"values\"></span>'+\n"
"      '<span data-control></span></div>';\n"
"    node.__built=true;\n"
"  }\n"
"  var h2=node.querySelector('h2');\n"
"  h2.textContent='';\n"
"  h2.appendChild(el('span',{'text':esc(ent.name)}));\n"
"  h2.appendChild(el('span',{'class':'entity-meta','text':' ('+esc(ent.device_id)+')'}));\n"
"  setText(node.querySelector('[data-field=\"devkey\"]'),t('common.id')+': '+esc(key));\n"
"  setText(node.querySelector('[data-field=\"meta\"]'),\n"
"    t('common.type')+': '+(ent.type||'')+' | '+t('entities.caps')+': '+((ent.capabilities||[]).join(', '))+' | '+t('common.unit')+': '+(ent.unit||''));\n"
"  var cmds=node.querySelector('[data-field=\"cmds\"]');\n"
"  cmds.textContent=t('common.state')+': ';\n"
"  var b=el('span',{'class':'badge '+badgeForStatus(ent.cmd_status)});\n"
"  setText(b,ent.cmd_status||'—');\n"
"  cmds.appendChild(b);\n"
"  setText(node.querySelector('[data-field=\"reliability\"]'),'Reliability: '+(ent.reliability==null?'':ent.reliability));\n"
"  setText(node.querySelector('[data-field=\"values\"]'),t('entities.current')+': '+fmtBool(ent.current)+'  '+t('entities.desired')+': '+fmtBool(ent.desired));\n"
"  updateEntityControl(ent,node);\n"
"}\n"
"function updateEntityControl(ent,node){\n"
"  var key=ent.device_id+'/'+ent.entity_id;\n"
"  var caps=ent.capabilities||[];\n"
"  var isRelay=caps.indexOf('actuator.relay')>=0;\n"
"  var isDimmer=caps.indexOf('actuator.dimmer')>=0;\n"
"  var type=isRelay?'relay':(isDimmer?'dimmer':'none');\n"
"  var holder=node.querySelector('[data-control]');\n"
"  var busy=uiState.pending.has(key);\n"
"  if(node.__ctlType!==type){\n"
"    holder.innerHTML='';\n"
"    if(type==='relay'){\n"
"      node.__ctl=el('button',{'class':'toggle','data-action':'toggle','data-k':key,'aria-label':t('nav.rules')});\n"
"      holder.appendChild(node.__ctl);\n"
"    } else if(type==='dimmer'){\n"
"      node.__ctl=el('input',{'type':'range','class':'slider','min':'0','max':'100','data-action':'dimmer','data-k':key});\n"
"      holder.appendChild(node.__ctl);\n"
"    } else {\n"
"      node.__ctl=null;\n"
"      holder.appendChild(document.createTextNode(fmtBool(ent.desired)));\n"
"    }\n"
"    node.__ctlType=type;\n"
"  }\n"
"  var ctl=node.__ctl;\n"
"  if(type==='relay'){\n"
"    setClass(ctl,'on',ent.desired===true);\n"
"    setAttr(ctl,'data-want',ent.desired===true?'1':'0');\n"
"    setDisabled(ctl,busy);\n"
"  } else if(type==='dimmer'){\n"
"    setDisabled(ctl,busy);\n"
"    var lv=(typeof ent.desired==='number')?ent.desired:(ent.current||0);\n"
"    /* Suppress echo while the user is dragging so the thumb does not jump. */\n"
"    if(ctl!==document.activeElement) setValue(ctl,lv);\n"
"  }\n"
"}\n"
"function handleToggle(t){\n"
"  if(t.disabled) return;\n"
"  var key=t.getAttribute('data-k');\n"
"  var kv=key.split('/');\n"
"  var want=(t.getAttribute('data-want')==='1');\n"
"  t.disabled=true; uiState.pending.add(key);\n"
"  apiFetch('/control/relay',{method:'POST',body:JSON.stringify({device_id:kv[0],entity_id:kv[1],value:!want})})\n"
"    .then(function(){ uiState.pending.delete(key); runViewRefresh(views.entities); })\n"
"    .catch(function(e){ uiState.pending.delete(key); showError(e); });\n"
"}\n"
"function handleDimmer(s){\n"
"  if(s.disabled) return;\n"
"  var key=s.getAttribute('data-k');\n"
"  var kv=key.split('/');\n"
"  s.disabled=true; uiState.pending.add(key);\n"
"  apiFetch('/control/dimmer',{method:'POST',body:JSON.stringify({device_id:kv[0],entity_id:kv[1],level:parseInt(s.value,10)})})\n"
"    .then(function(){ uiState.pending.delete(key); runViewRefresh(views.entities); })\n"
"    .catch(function(e){ uiState.pending.delete(key); showError(e); });\n"
"}\n"
"views.entities={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"section-header\"><h2 data-i18n=\"nav.entities\">Entities</h2><span class=\"empty\"></span></div><div id=\"entityList\" class=\"grid grid-2\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#entityList');\n"
"    this.__count=host.querySelector('.section-header .empty');\n"
"    /* Event delegation: installed once at mount, never re-attached. */\n"
"    host.addEventListener('click',function(e){\n"
"      var t=e.target.closest?e.target.closest('[data-action=\"toggle\"]'):null;\n"
"      if(t){ e.preventDefault(); handleToggle(t); }\n"
"    });\n"
"    host.addEventListener('change',function(e){\n"
"      var s=e.target.closest?e.target.closest('[data-action=\"dimmer\"]'):null;\n"
"      if(s) handleDimmer(s);\n"
"    });\n"
"  },\n"
"  refresh:makeRefresh('/entities','entities'),\n"
"  update:function(d){\n"
"    var list=d||[];\n"
"    setText(this.__count,list.length+'');\n"
"    reconcileCollection(this.__list,list,function(x){return x.device_id+'/'+x.entity_id;},'data-entity-key',entityCardNew,updateEntityCard);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * RULES view (collection refreshed incrementally; editor is an overlay)\n"
" * ===================================================================== */\n"
"function ruleBrief(rule){\n"
"  if(rule.trigger&&rule.trigger.length){\n"
"    var t0=rule.trigger[0];\n"
"    if(t0&&t0.entity) return esc(t0.entity.device_id+'/'+t0.entity.entity_id)+' '+(t0.operator?esc(t0.operator):'')+' '+esc(t0.threshold);\n"
"  }\n"
"  return '—';\n"
"}\n"
"function ruleCardNew(){ return el('div',{'class':'card','data-rule-key':''}); }\n"
"function updateRuleCard(rule,node){\n"
"  if(!node.__built){\n"
"    node.innerHTML=''+\n"
"      '<h2></h2>'+\n"
"      '<div class=\"entity\"><div class=\"entity-info\">'+\n"
"      '<span class=\"entity-name\" data-field=\"id\"></span>'+\n"
"      '<span class=\"entity-meta\" data-field=\"meta\"></span>'+\n"
"      '<span class=\"entity-meta\" data-field=\"trigger\"></span></div>'+\n"
"      '<span class=\"badge\" data-field=\"enabled\"></span></div>'+\n"
"      '<div style=\"margin-top:8px;display:flex;gap:8px;flex-wrap:wrap\">'+\n"
"      '<button class=\"btn btn-ghost\" data-action=\"edit-rule\"></button>'+\n"
"      '<button class=\"btn\" data-action=\"toggle-rule\"></button>'+\n"
"      '<button class=\"btn btn-danger\" data-action=\"del-rule\"></button></div>';\n"
"    node.__built=true;\n"
"  }\n"
"  var h2=node.querySelector('h2');\n"
"  h2.textContent='';\n"
"  h2.appendChild(el('span',{'text':esc(rule.name)}));\n"
"  setText(node.querySelector('[data-field=\"id\"]'),t('common.id')+': '+rule.rule_id);\n"
"  setText(node.querySelector('[data-field=\"meta\"]'),t('common.revision')+': '+(rule.revision||0));\n"
"  setText(node.querySelector('[data-field=\"trigger\"]'),t('common.trigger')+': '+(rule.trigger&&rule.trigger.length?ruleBrief(rule):'—'));\n"
"  var eb=node.querySelector('[data-field=\"enabled\"]');\n"
"  setText(eb,rule.enabled?t('rules.enabled'):t('rules.disabled'));\n"
"  setClass(eb,'badge-enabled',!!rule.enabled);\n"
"  setClass(eb,'badge-disabled',!rule.enabled);\n"
"  node.querySelector('[data-action=\"edit-rule\"]').setAttribute('data-rule',rule.rule_id);\n"
"  setText(node.querySelector('[data-action=\"edit-rule\"]'),t('common.edit'));\n"
"  var tb=node.querySelector('[data-action=\"toggle-rule\"]');\n"
"  tb.setAttribute('data-rule',rule.rule_id);\n"
"  setText(tb,rule.enabled?t('common.disable'):t('common.enable'));\n"
"  setClass(tb,'btn-danger',!!rule.enabled);\n"
"  setClass(tb,'btn-primary',!rule.enabled);\n"
"  node.querySelector('[data-action=\"del-rule\"]').setAttribute('data-rule',rule.rule_id);\n"
"  setText(node.querySelector('[data-action=\"del-rule\"]'),t('common.delete'));\n"
"}\n"
"views.rules={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"section-header\"><h2 data-i18n=\"nav.rules\">Rules</h2>'+\n"
"      '<span class=\"empty\"></span>'+\n"
"      '<button class=\"btn btn-primary\" data-action=\"new-rule\" data-i18n=\"rules.create\">Create Rule</button></div><div id=\"ruleList\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#ruleList');\n"
"    this.__count=host.querySelector('.section-header .empty');\n"
"    host.addEventListener('click',function(e){\n"
"      var t=null;\n"
"      if(e.target.closest) t=e.target.closest('[data-action]');\n"
"      if(!t) return;\n"
"      var a=t.getAttribute('data-action');\n"
"      if(a==='new-rule') openRuleEditor(null);\n"
"      else if(a==='edit-rule') openRuleEditor(t.getAttribute('data-rule'));\n"
"      else if(a==='toggle-rule') toggleRule(t.getAttribute('data-rule'));\n"
"      else if(a==='del-rule') deleteRule(t.getAttribute('data-rule'));\n"
"    });\n"
"  },\n"
"  refresh:makeRefresh('/rules','rules'),\n"
"  update:function(r){\n"
"    var list=r||[];\n"
"    setText(this.__count,list.length+'');\n"
"    reconcileCollection(this.__list,list,function(x){return x.rule_id;},'data-rule-key',ruleCardNew,updateRuleCard);\n"
"  }\n"
"};\n"
"function toggleRule(id){\n"
"  var card=document.querySelector('[data-rule-key=\"'+id+'\"]');\n"
"  var enDiag=card?card.querySelector('[data-field=\"enabled\"]').textContent:'';\n"
"  var en=(enDiag===t('rules.enabled'));\n"
"  apiFetch('/rules/'+encodeURIComponent(id)+(en?'/disable':'/enable'),{method:'POST'})\n"
"    .then(function(){ runViewRefresh(views.rules); })\n"
"    .catch(showError);\n"
"}\n"
"function deleteRule(id){\n"
"  if(!window.confirm(tf('common.delete_q',{0:id}))) return;\n"
"  apiFetch('/rules/'+encodeURIComponent(id),{method:'DELETE'})\n"
"    .then(function(){ runViewRefresh(views.rules); })\n"
"    .catch(showError);\n"
"}\n"
"\n"
"/* ---- Rule editor (overlay, not part of the collection DOM) ---- */\n"
"function collectRuleBody(f){\n"
"  var body={name:f.name.value};\n"
"  if(f.rule_id&&f.rule_id.value) body.rule_id=f.rule_id.value;\n"
"  body.trigger={entity:{device_id:f.trg_dev.value,entity_id:f.trg_ent.value},operator:f.trg_op.value,threshold:parseFloat(f.trg_threshold.value)};\n"
"  body.actions=[{entity:{device_id:f.act_dev.value,entity_id:f.act_ent.value},action:f.act_type.value,value:parseFloat(f.act_value.value)}];\n"
"  if(f.cooldown_ms.value) body.cooldown_ms=parseInt(f.cooldown_ms.value,10);\n"
"  if(f.priority.value) body.priority=parseInt(f.priority.value,10);\n"
"  if(f.max_act.value) body.max_activations_per_hour=parseInt(f.max_act.value,10);\n"
"  body.enabled=true;\n"
"  return body;\n"
"}\n"
"function closeRuleEditor(){\n"
"  overlayEl.style.display='none';\n"
"  overlayEl.innerHTML='';\n"
"  uiState.formActive=false;\n"
"  uiState.editingRuleId=null;\n"
"  runViewRefresh(views.rules);\n"
"}\n"
"function openRuleEditor(id){\n"
"  uiState.formActive=true;\n"
"  uiState.editingRuleId=id;\n"
"  overlayEl.style.display='block';\n"
"  if(id){\n"
"    apiFetch('/rules/'+encodeURIComponent(id)).then(function(rule){\n"
"      buildRuleForm(rule);\n"
"    }).catch(showError);\n"
"  } else {\n"
"    buildRuleForm(null);\n"
"  }\n"
"}\n"
"function buildRuleForm(rule){\n"
"  var card=el('div',{'class':'card'},[\n"
"    el('h2',{'text':rule?t('rules.edit'):t('rules.create')}),\n"
"    el('form',{'id':'ruleForm'})\n"
"  ]);\n"
"  var form=card.querySelector('form');\n"
"  var trig=(rule&&rule.trigger&&rule.trigger.length)?rule.trigger[0]:null;\n"
"  var actions=(rule&&rule.actions&&rule.actions.length)?rule.actions:[];\n"
"  var act=actions[0]||null;\n"
"  addRow(form,t('rules.form.name'),input('name',rule?rule.name:''),true);\n"
"  addRow(form,t('rules.form.rule_id'),input('rule_id',(rule?rule.rule_id:'')));\n"
"  addRow(form,t('rules.form.trg_dev'),input('trg_dev',trig?(trig.entity?trig.entity.device_id:''):'dashboard'));\n"
"  addRow(form,t('rules.form.trg_ent'),input('trg_ent',trig?(trig.entity?trig.entity.entity_id:''):'temperature'));\n"
"  addRow(form,t('rules.form.operator'),sel('trg_op',[['GT','>'],['LT','<'],['GE','≥'],['LE','≤'],['EQ','='],['NE','≠']],trig?trig.operator:'GT'));\n"
"  addRow(form,t('rules.form.threshold'),input('trg_threshold','number',trig?trig.threshold:30));\n"
"  addRow(form,t('rules.form.act_dev'),input('act_dev',act?(act.entity?act.entity.device_id:''):'dashboard'));\n"
"  addRow(form,t('rules.form.act_ent'),input('act_ent',act?(act.entity?act.entity.entity_id:''):'fan'));\n"
"  addRow(form,t('rules.form.act_type'),sel('act_type',[['SET_BOOL',t('rules.act.SET_BOOL')],['SET_LEVEL',t('rules.act.SET_LEVEL')],['SET_VALUE',t('rules.act.SET_VALUE')],['TOGGLE',t('rules.act.TOGGLE')]],act?act.action:'SET_BOOL'));\n"
"  addRow(form,t('rules.form.value'),input('act_value','number',act?(act.value==null?1:act.value):1));\n"
"  addRow(form,t('rules.form.cooldown'),input('cooldown_ms','number',rule?rule.cooldown_ms:60000));\n"
"  addRow(form,t('rules.form.priority'),input('priority','number',rule?rule.priority:10));\n"
"  addRow(form,t('rules.form.max_act'),input('max_act','number',rule?rule.max_activations_per_hour:10));\n"
"  var save=el('button',{'type':'button','class':'btn btn-primary','style':'margin-top:12px;width:100%'},{'text':t('common.save')});\n"
"  var cancel=el('button',{'type':'button','class':'btn btn-ghost','style':'margin-top:8px;width:100%'},{'text':t('common.cancel')});\n"
"  var btnRow=el('div',{'style':'margin-top:12px'},[save,cancel]);\n"
"  form.appendChild(btnRow);\n"
"  save.addEventListener('click',function(){ saveRuleForm(); });\n"
"  cancel.addEventListener('click',function(){ closeRuleEditor(); });\n"
"  overlayEl.innerHTML='';\n"
"  overlayEl.appendChild(card);\n"
"}\n"
"function addRow(form,labelText,inputEl){\n"
"  var d=el('div');\n"
"  d.appendChild(el('label',{'text':labelText}));\n"
"  d.appendChild(inputEl);\n"
"  form.appendChild(d);\n"
"}\n"
"function input(name,value,type){\n"
"  var i=el('input',{'name':name,'type':type||'text','value':value==null?'':value});\n"
"  return i;\n"
"}\n"
"function sel(name,opts,selVal){\n"
"  var s=el('select',{'name':name});\n"
"  opts.forEach(function(o){\n"
"    var v=o[0],lab=o[1];\n"
"    var opt=el('option',{'value':v,'text':lab});\n"
"    if(String(v)===String(selVal)) setAttr(opt,'selected','selected');\n"
"    s.appendChild(opt);\n"
"  });\n"
"  return s;\n"
"}\n"
"function saveRuleForm(){\n"
"  var f=document.getElementById('ruleForm');\n"
"  if(!f) return;\n"
"  var fels=f.elements;\n"
"  var elt=fels.name;\n"
"  if(!elt||!elt.value.trim()){ showError(new Error(t('rules.name_req'))); return; }\n"
"  var body=collectRuleBody(fels);\n"
"  var id=uiState.editingRuleId;\n"
"  var isNew=!id;\n"
"  apiFetch(isNew?'/rules':'/rules/'+encodeURIComponent(id),{method:isNew?'POST':'PUT',body:JSON.stringify(body)})\n"
"    .then(function(){\n"
"      closeRuleEditor();\n"
"    }).catch(showError);\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * SKILLS view (rarely changes; reconciled incrementally anyway)\n"
" * ===================================================================== */\n"
"function skillCardNew(){ return el('div',{'class':'card','data-skill-key':''}); }\n"
"function updateSkillCard(sk,node){\n"
"  if(!node.__built){\n"
"    node.innerHTML=''+\n"
"      '<h2></h2>'+\n"
"      '<div class=\"entity\"><div class=\"entity-info\">'+\n"
"      '<span class=\"entity-name\" data-field=\"ver\"></span>'+\n"
"      '<span class=\"entity-meta\" data-field=\"desc\"></span>'+\n"
"      '<span class=\"entity-meta\" data-field=\"schema\"></span>'+\n"
"      '<span class=\"entity-meta\" data-field=\"perms\"></span></div></div>';\n"
"    node.__built=true;\n"
"  }\n"
"  var h2=node.querySelector('h2');\n"
"  h2.textContent='';\n"
"  h2.appendChild(el('span',{'text':esc(sk.name)}));\n"
"  setText(node.querySelector('[data-field=\"ver\"]'),'v'+sk.version);\n"
"  setText(node.querySelector('[data-field=\"desc\"]'),sk.description||'');\n"
"  setText(node.querySelector('[data-field=\"schema\"]'),t('common.schema')+': '+(sk.schema_id||''));\n"
"  var perms='';\n"
"  if(sk.permissions&1) perms+='READ ';\n"
"  if(sk.permissions&2) perms+='CONTROL ';\n"
"  if(sk.permissions&4) perms+='RULE_READ ';\n"
"  if(sk.permissions&8) perms+='RULE_WRITE ';\n"
"  setText(node.querySelector('[data-field=\"perms\"]'),t('common.perms')+': '+perms);\n"
"}\n"
"views.skills={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"section-header\"><h2 data-i18n=\"skills.title\">Skills</h2><span class=\"empty\"></span></div><div id=\"skillList\" class=\"grid grid-2\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#skillList');\n"
"    this.__count=host.querySelector('.section-header .empty');\n"
"  },\n"
"  refresh:makeRefresh('/skills','skills'),\n"
"  update:function(sk){\n"
"    var list=sk||[];\n"
"    setText(this.__count,list.length+'');\n"
"    reconcileCollection(this.__list,list,function(x){return x.name;},'data-skill-key',skillCardNew,updateSkillCard);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * LOGS view (append new, remove overflow, keep DOM stable)\n"
" * ===================================================================== */\n"
"function logKey(e){\n"
"  var ts=(typeof e.ts==='number')?e.ts:(e.timestamp?e.timestamp.seconds:0);\n"
"  return ts+':'+(e.source||'')+':'+(e.msg||'');\n"
"}\n"
"function logCardNew(){ return el('div',{'class':'log-entry','data-log-key':''}); }\n"
"function updateLogCard(e,node){\n"
"  var lvl=String(e.level||e.layer||'');\n"
"  setClass(node,'ERROR',lvl==='ERROR');\n"
"  setClass(node,'WARNING',lvl==='WARNING');\n"
"  var ts=(typeof e.ts==='number')?e.ts:(e.timestamp?e.timestamp.seconds:0);\n"
"  node.textContent='';\n"
"  node.appendChild(el('span',{'style':'color:var(--text-faint)','text':'['+fmtTs(ts)+']'}));\n"
"  node.appendChild(el('span',{'style':'font-weight:500','text':(e.source||'')+': '}));\n"
"  node.appendChild(el('span',{'text':e.msg||''}));\n"
"}\n"
"views.logs={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"section-header\"><h2 data-i18n=\"logs.title\">Logs</h2><span class=\"empty\"></span></div><div id=\"logList\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#logList');\n"
"    this.__count=host.querySelector('.section-header .empty');\n"
"  },\n"
"  refresh:makeRefresh('/logs','logs'),\n"
"  update:function(l){\n"
"    var list=(l||[]).slice(0,50);\n"
"    setText(this.__count,list.length+'');\n"
"    reconcileCollection(this.__list,list,logKey,'data-log-key',logCardNew,updateLogCard);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * SYSTEM view\n"
" * ===================================================================== */\n"
"views.system={\n"
"  mount:function(host){\n"
"    host.innerHTML=\n"
"      '<div class=\"grid grid-3\">'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"system.net\">Network</h2><div class=\"metric\" data-field=\"net\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"system.ssid\">SSID</h2><div class=\"metric\" data-field=\"ssid\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"system.ip\">IP</h2><div class=\"metric\" data-field=\"ip\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"system.heap\">Heap</h2><div class=\"metric\" data-field=\"heap\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"system.uptime\">Uptime</h2><div class=\"metric\" data-field=\"uptime\">—</div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"system.build\">Build</h2><div class=\"metric\" data-field=\"build\">ESP32 Dashboard</div></div>'+\n"
"      '</div>';\n"
"    applyI18n(host);\n"
"    var f={};\n"
"    ['net','ssid','ip','heap','uptime','build'].forEach(function(n){\n"
"      f[n]=host.querySelector('[data-field=\"'+n+'\"]');\n"
"    });\n"
"    this.__f=f;\n"
"  },\n"
"  refresh:makeRefresh('/status','system'),\n"
"  update:function(s){\n"
"    var f=this.__f;\n"
"    setNetLabel(netLabelFor(s));\n"
"    setText(f.net,s.network===void 0?'?':String(s.network));\n"
"    setText(f.ssid,s.ssid||'—');\n"
"    setText(f.ip,s.ip||'—');\n"
"    setText(f.heap,s.free_heap+' B');\n"
"    setText(f.uptime,Math.floor(s.uptime_ms/1000)+'s');\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * NETWORK view (mount-once, explicit scan, never auto-refreshed).\n"
" * pollable:false keeps the Setup form untouched by any polling.\n"
" * ===================================================================== */\n"
"var scanCache=[];\n"
"views.network={\n"
"  pollable:false,\n"
"  mount:function(host){\n"
"    host.innerHTML=\n"
"      '<div class=\"card\"><p class=\"entity-meta\" data-i18n=\"network.hint\">Configure this device to join your local WiFi. After saving it reboots in STA mode (no more AP).</p></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"network.scan\">Scan Networks</h2>'+\n"
"        '<button class=\"btn btn-primary\" id=\"scanBtn\" data-i18n=\"network.scan_btn\">Scan for networks</button>'+\n"
"        '<div id=\"scanList\" style=\"margin-top:12px\"></div></div>'+\n"
"      '<div class=\"card\"><h2 data-i18n=\"network.connect\">Connect to WiFi</h2>'+\n"
"        '<div class=\"form-row\"><div><label data-i18n=\"network.ssid\">SSID</label><input id=\"netSsid\" list=\"scanOpts\" data-i18n-ph=\"network.ssid_ph\" placeholder=\"Network name...\"></div>'+\n"
"        '<div><label data-i18n=\"network.password\">Password</label><input id=\"netPassword\" type=\"password\" data-i18n-ph=\"network.password_ph\" placeholder=\"Leave empty for open networks\"></div></div>'+\n"
"        '<div class=\"form-row\"><div><label data-i18n=\"network.udp_disc\">UDP Discovery Port</label><input id=\"netUdpDiscovery\" type=\"number\" value=\"13345\" min=\"1\" placeholder=\"13345\"></div>'+\n"
"        '<div><label data-i18n=\"network.udp_ctrl\">UDP Control Port</label><input id=\"netUdpControl\" type=\"number\" value=\"13346\" min=\"1\" placeholder=\"13346\"></div></div>'+\n"
"        '<datalist id=\"scanOpts\"></datalist>'+\n"
"        '<label><input type=\"checkbox\" id=\"netEnable\" checked style=\"width:auto;margin-right:6px\"><span data-i18n=\"network.sta_enable\">Enable STA (connect on boot)</span></label>'+\n"
"        '<div style=\"margin-top:12px\"><button class=\"btn btn-primary\" id=\"connectBtn\" data-i18n=\"network.save_reboot\">Save & Reboot</button> <span id=\"netMsg\" class=\"empty\"></span></div>'+\n"
"      '</div>';\n"
"    applyI18n(host);\n"
"    var scanBtn=document.getElementById('scanBtn');\n"
"    var connectBtn=document.getElementById('connectBtn');\n"
"    var msg=document.getElementById('netMsg');\n"
"    var scanList=document.getElementById('scanList');\n"
"    var scanOpts=document.getElementById('scanOpts');\n"
"    var ssidEl=document.getElementById('netSsid');\n"
"    var passEl=document.getElementById('netPassword');\n"
"    var enableEl=document.getElementById('netEnable');\n"
"    var renderScanList=function(nets){\n"
"      if(!nets.length){ scanList.innerHTML='<div class=\"empty\" data-i18n=\"network.no_nets\">No networks found. Try scanning again.</div>'; applyI18n(scanList); return; }\n"
"      scanList.innerHTML='<div class=\"empty\" style=\"margin-bottom:6px\" data-i18n=\"network.click_ssid\">Click an SSID to select it:</div>'+\n"
"        nets.map(function(n){\n"
"          return '<button class=\"btn btn-ghost\" style=\"width:auto;margin:2px 4px\" data-ssid=\"'+esc(n.ssid)+'\">'+esc(n.ssid)+' ('+esc(n.rssi)+' dBm)</button>';\n"
"        }).join('');\n"
"      applyI18n(scanList);\n"
"      scanOpts.innerHTML=nets.map(function(n){ return '<option value=\"'+esc(n.ssid)+'\">'; }).join('');\n"
"    };\n"
"    /* Delegation: scan buttons are recreated per scan, so listen once here. */\n"
"    scanList.addEventListener('click',function(e){\n"
"      var b=e.target.closest?e.target.closest('[data-ssid]'):null;\n"
"      if(b) setValue(ssidEl,b.getAttribute('data-ssid'));\n"
"    });\n"
"    scanBtn.addEventListener('click',function(){\n"
"      msg.textContent=t('network.scanning');\n"
"      setDisabled(scanBtn,true);\n"
"      apiFetch('/wifi/scan').then(function(nets){\n"
"        scanCache=nets||[];\n"
"        renderScanList(scanCache);\n"
"        msg.textContent=tf('network.found',{0:scanCache.length});\n"
"        setDisabled(scanBtn,false);\n"
"      }).catch(function(){ msg.textContent=t('network.scan_failed'); setDisabled(scanBtn,false); });\n"
"    });\n"
"    connectBtn.addEventListener('click',function(){\n"
"      var ssid=ssidEl.value.trim();\n"
"      if(!ssid){ msg.textContent=t('network.ssid_req'); return; }\n"
"      var password=passEl.value;\n"
"      var enable=enableEl.checked;\n"
"      var udpDiscovery=document.getElementById('netUdpDiscovery').value||'13345';\n"
"      var udpControl=document.getElementById('netUdpControl').value||'13346';\n"
"      msg.textContent=t('common.saving');\n"
"      setDisabled(connectBtn,true);\n"
"      apiFetch('/wifi/connect',{method:'POST',body:JSON.stringify({ssid:ssid,password:password,enabled:enable,udp_discovery_port:Number(udpDiscovery),udp_control_port:Number(udpControl)})})\n"
"        .then(function(){ msg.textContent=t('network.saved'); setTimeout(function(){ setOnline(false); },500); })\n"
"        .catch(function(){ msg.textContent=t('network.save_failed'); setDisabled(connectBtn,false); });\n"
"    });\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * Wiring (runs once after all views are defined).\n"
" * ===================================================================== */\n"
"navTabs.addEventListener('click',function(e){\n"
"  var b=e.target.closest?e.target.closest('.tab'):null;\n"
"  if(!b||!b.getAttribute('data-tab')) return;\n"
"  e.preventDefault();\n"
"  showView(b.getAttribute('data-tab'));\n"
"});\n"
"/* Every apiFetch call site has its own .catch, so any unhandled rejection is\n"
" * a bug, not a live connectivity change - do not flip the global indicator. */\n"
"\n"
"buildThemePicker();\n"
"buildNav();\n"
"loadPrefs();\n"
"setOnline(false);\n"
"setInterval(pollTick,10000);\n"
"showView('dashboard');\n"
"\n"
"function loadPrefs(){\n"
"  var t0='dark',l='es';\n"
"  try{ t0=localStorage.getItem('qymera_theme')||'dark'; l=localStorage.getItem('qymera_lang')||'es'; }catch(e){}\n"
"  if(l!=='es'&&l!=='en') l='es';\n"
"  applyLang(l);\n"
"  applyI18n(document.body);\n"
"  setTheme(t0);\n"
"}\n"
"</script>\n"
"</body>\n"
"</html>\n";
